    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge bg-danger fs-6">@AlertService.LastLowStockCount</span>
        </p>
        <p class="text-muted">Polling every 10 seconds…</p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private Timer? _timer;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
        StartPolling();
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        // Fire immediately, then every 10 seconds
        _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
    }

    private async void PollCallback(object? state)
    {
        if (_cts?.IsCancellationRequested == true) return;

        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        AlertService.UpdateAlertCount(count);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling immediately for new warehouse
        InvokeAsync(() =>
        {
            StartPolling();
            StateHasChanged();
        });
    }

    private void OnAlertChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
        StopPolling();
        _cts?.Dispose();
    }
}

